import React from "react";
import { Link } from "react-router-dom";
import HistoryTableRow from "./HistoryTableRowComponent";
import Loader from "./LoaderComponent";
import withRouter from "./withRouter";
import "./../css/profie.css";

const API_URL = "https://iranaserviceapp.ir/test/api";
const IMAGE_URL = "https://iranaserviceapp.ir/test/files/user";

const DEFAULT_AVATAR =
  "https://ui-avatars.com/api/?name=کاربر&background=e9ecef&color=495057";

function toPersianDigits(value) {
  if (value === null || value === undefined) {
    return "";
  }

  const digits = "۰۱۲۳۴۵۶۷۸۹";

  return String(value).replace(
    /\d/g,
    (digit) => digits[Number(digit)]
  );
}

function formatDate(dateString) {
  if (!dateString) {
    return "";
  }

  const parts = String(dateString).split("/");

  if (parts.length !== 3) {
    return dateString;
  }

  const year = Number(parts[0]);
  const month = Number(parts[1]);
  const day = Number(parts[2]);

  // اگر تاریخ از قبل شمسی باشد
  if (year < 1700) {
    return `${toPersianDigits(year)}/${toPersianDigits(
      String(month).padStart(2, "0")
    )}/${toPersianDigits(
      String(day).padStart(2, "0")
    )}`;
  }

  try {
    const date = new Date(year, month - 1, day);

    return new Intl.DateTimeFormat(
      "fa-IR-u-ca-persian",
      {
        year: "numeric",
        month: "2-digit",
        day: "2-digit",
      }
    ).format(date);
  } catch (error) {
    console.error("DATE FORMAT ERROR:", error);
    return dateString;
  }
}

function getMonthLabel(dateString) {
  if (!dateString) {
    return "";
  }

  const parts = String(dateString).split("/");

  if (parts.length !== 3) {
    return "";
  }

  const year = Number(parts[0]);
  const month = Number(parts[1]);
  const day = Number(parts[2]);

  try {
    if (year < 1700) {
      return `${toPersianDigits(year)}/${toPersianDigits(
        String(month).padStart(2, "0")
      )}`;
    }

    const date = new Date(year, month - 1, day);

    return new Intl.DateTimeFormat(
      "fa-IR-u-ca-persian",
      {
        year: "numeric",
        month: "long",
      }
    ).format(date);
  } catch (error) {
    console.error("MONTH FORMAT ERROR:", error);
    return "";
  }
}

function getRequestStatus(request) {
  if (
    Number(request.status) === 1 &&
    Number(request.end) === 2
  ) {
    return "success";
  }

  return "canceled";
}

function getAvatar(repairman) {
  if (!repairman) {
    return DEFAULT_AVATAR;
  }

  if (repairman.image) {
    return `${IMAGE_URL}${repairman.image}`;
  }

  const fullName =
    `${repairman.name || ""} ${
      repairman.family || ""
    }`.trim();

  return `https://ui-avatars.com/api/?name=${encodeURIComponent(
    fullName || "کاربر"
  )}&background=e9ecef&color=495057`;
}

function calculateStats(requests) {
  const settled = requests.filter(
    (request) =>
      Number(request.status) === 1 &&
      Number(request.end) === 2
  ).length;

  const canceledByTechnician =
    requests.filter(
      (request) =>
        Number(request.status) !== 1
    ).length;

  const reactivated =
    requests.filter(
      (request) =>
        Number(request.cleared) === 1
    ).length;

  return {
    settled,
    canceledByTechnician,
    reactivated,
  };
}

class TechnicianProfilePage extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      profile: null,

      stats: {
        settled: 0,
        canceledByTechnician: 0,
        reactivated: 0,
      },

      history: [],

      loading: true,

      error: "",
    };
  }

  componentDidMount() {
    this.getUserHistory();
  }

  // ==========================================
  // دریافت اطلاعات تعمیرکار
  // ==========================================

  getUserHistory = async () => {
    // ID از Route
    // مثال:
    // /user-history/63

    const { id } = this.props.params;

    console.log("USER ID:", id);

    if (!id) {
      this.setState({
        loading: false,
        error: "شناسه تعمیرکار پیدا نشد.",
      });

      return;
    }

    const token =
      localStorage.getItem("token");

    if (!token) {
      this.setState({
        loading: false,
        error: "توکن ورود پیدا نشد.",
      });

      return;
    }

    const url =
      `${API_URL}/user-history?id=${encodeURIComponent(
        id
      )}`;

    console.log("REQUEST URL:", url);

    try {
      const response = await fetch(url, {
        method: "GET",

        headers: {
          Accept: "application/json",
          Authorization: `Bearer ${token}`,
        },
      });

      console.log(
        "HTTP STATUS:",
        response.status
      );

      if (!response.ok) {
        throw new Error(
          `HTTP ${response.status}`
        );
      }

      const data =
        await response.json();

      console.log(
        "USER HISTORY RESPONSE:",
        data
      );

      if (String(data.status) !== "1") {
        this.setState({
          loading: false,
          error:
            data.message ||
            "اطلاعاتی پیدا نشد.",
          profile: null,
          history: [],
        });

        return;
      }

      const requests =
        Array.isArray(data.requests)
          ? data.requests
          : [];

      // ==========================================
      // اطلاعات تعمیرکار
      // ==========================================

      const repairman =
        requests.length > 0
          ? requests[0].repairman_model
          : null;

      const fullName = repairman
        ? `${repairman.name || ""} ${
            repairman.family || ""
          }`.trim()
        : "بدون نام";

      const profile = {
        id: repairman?.id || id,

        name:
          fullName || "بدون نام",

        confirmedRequests:
          requests.length,

        avatar:
          getAvatar(repairman),
      };

      // ==========================================
      // تبدیل سوابق
      // ==========================================

      const history =
        requests.map((request) => ({
          id: request.id,

          deviceType:
            request.device_type ||
            "نامشخص",

          issue:
            request.problem ||
            "بدون توضیحات",

          date:
            formatDate(request.time),

          status:
            getRequestStatus(request),

          originalData:
            request,
        }));

      // ==========================================
      // آمار
      // ==========================================

      const stats =
        calculateStats(requests);

      // ==========================================
      // ذخیره اطلاعات
      // ==========================================

      this.setState({
        profile,
        stats,
        history,
        loading: false,
        error: "",
      });
    } catch (error) {
      console.error(
        "USER HISTORY ERROR:",
        error
      );

      this.setState({
        loading: false,
        profile: null,
        history: [],
        error:
          "خطا در دریافت اطلاعات تعمیرکار.",
      });
    }
  };

  // ==========================================
  // نمایش سوابق
  // ==========================================

  renderHistory() {
    const {
      history,
    } = this.state;

    let lastMonth = "";

    return history.map((record) => {
      const month =
        getMonthLabel(
          record.originalData.time
        );

      const showMonth =
        month && month !== lastMonth;

      lastMonth = month;

      return (
        <React.Fragment key={record.id}>

          {showMonth && (
            <div className="text-center small text-muted py-2 bg-light border-bottom">
              {month}
            </div>
          )}

          <Link
            to={`/request-details/${record.id}`}
            className="text-decoration-none text-dark d-block"
          >
            <HistoryTableRow
              record={record}
            />
          </Link>

        </React.Fragment>
      );
    });
  }

  render() {
    const {
      profile,
      stats,
      history,
      loading,
      error,
    } = this.state;

    // ==========================================
    // Loader
    // ==========================================

    if (loading) {
      return <Loader />;
    }

    // ==========================================
    // Error
    // ==========================================

    if (error) {
      return (
        <div
          dir="rtl"
          className="container px-3 py-5"
        >
          <div className="text-center text-danger">
            {error}
          </div>
        </div>
      );
    }

    if (!profile) {
      return (
        <div
          dir="rtl"
          className="container px-3 py-5"
        >
          <div className="text-center text-muted">
            اطلاعات تعمیرکار پیدا نشد.
          </div>
        </div>
      );
    }

    return (
      <div dir="rtl">
        <div className="container px-3 pt-4 pb-5">

          {/* ========================================
              پروفایل تعمیرکار
          ======================================== */}

          <div className="d-flex align-items-center justify-content-between border rounded-4 p-3 mb-4">

            <div className="d-flex align-items-center gap-3 w-100">

              <img
                src={profile.avatar}
                alt={profile.name}
                width="56"
                height="56"
                className="rounded-circle"
                style={{
                  objectFit: "cover",
                }}
              />

              <div>
                <div className="fw-semibold text-dark">
                  {profile.name}
                </div>

                <div className="text-muted small">
                  {toPersianDigits(
                    profile.confirmedRequests
                  )}{" "}
                  درخواست تایید شده
                </div>
              </div>

              <div className="d-flex flex-column gap-2 me-auto">

                <Link
                  to={`/PersonalInfoPage/${profile.id}`}
                  className="btn btn-primary rounded-pill btn-sm px-4 py-2"
                >
                  پروفایل
                </Link>

                <button
                  type="button"
                  className="btn btn-outline-primary rounded-pill btn-sm px-4 py-2"
                >
                  گفتگو
                </button>

              </div>
            </div>
          </div>

          {/* ========================================
              آمار
          ======================================== */}

          <h2 className="text-center fs-6 fw-semibold text-dark mb-3">
            آمار
          </h2>

          <div className="border rounded-4 p-3 mb-4 d-flex flex-column gap-3">

            <div className="d-flex align-items-center justify-content-between">
              <span className="text-muted">
                تسویه شده
              </span>

              <span
                className="fw-semibold"
                style={{
                  color: "#5b9bf0",
                }}
              >
                {toPersianDigits(
                  stats.settled
                )}
              </span>
            </div>

            <div className="d-flex align-items-center justify-content-between">
              <span className="text-muted">
                کنسل شده توسط تعمیرکار
              </span>

              <span className="fw-semibold text-danger">
                {toPersianDigits(
                  stats.canceledByTechnician
                )}
              </span>
            </div>

            <div className="d-flex align-items-center justify-content-between">
              <span className="text-muted">
                مجدد فعال‌سازی شده
              </span>

              <span className="fw-semibold text-dark">
                {toPersianDigits(
                  stats.reactivated
                )}
              </span>
            </div>

          </div>

          {/* ========================================
              سوابق
          ======================================== */}

          <h2 className="text-center fs-6 fw-semibold text-dark mb-3">
            سوابق
          </h2>

          <div className="border rounded-4 overflow-hidden">

            <div
              className="py-3 border-bottom table-header"
              style={{
                display: "grid",
                gridTemplateColumns:
                  "1fr 1.3fr 1fr 0.8fr",
                alignItems: "center",
              }}
            >
              <span className="text-center small">
                نوع دستگاه
              </span>

              <span className="text-center small">
                ایراد دستگاه
              </span>

              <span className="text-center small">
                زمان مراجعه
              </span>

              <span className="text-center small">
                جزئیات
              </span>
            </div>

            {history.length === 0 ? (
              <div className="text-center text-muted py-5">
                سابقه‌ای برای این تعمیرکار وجود ندارد.
              </div>
            ) : (
              this.renderHistory()
            )}

          </div>

        </div>
      </div>
    );
  }
}

export default withRouter(TechnicianProfilePage);
